#pragma once
#include "model.h"
#include "logical.h"
// Generated from tools/update_example_notes.py. Keep descriptions in that script.
inline void annotateExample(Model &model,const QString &key){
 QString text;
 if(key=="orders")text=QString::fromUtf8("Ordini e righe dell’ordine\nUn ordine raccoglie le righe che descrivono ciò che viene richiesto. Può essere ancora vuoto, per esempio mentre lo stiamo compilando. Ogni riga appartiene invece a un solo ordine.\nNumeroOrdine distingue un ordine dagli altri. NumeroRiga distingue le righe dello stesso ordine: la riga 1 dell’ordine 15 è diversa dalla riga 1 dell’ordine 28. Per questo RigaOrdine è un’entità debole.\nGenerando il logico, osserva la chiave di RigaOrdine: contiene sia NumeroRiga sia il riferimento a Ordine. Prova poi a rendere obbligatoria la presenza di almeno una riga per ordine e leggi il controllo aggiuntivo indicato nel riepilogo.");
 if(key=="shop")text=QString::fromUtf8("Un negozio e i suoi clienti\nIl negozio vende prodotti a clienti privati e aziende. I clienti effettuano ordini; ogni riga di un ordine riguarda un prodotto. Un ordine può avere una fattura. I prodotti sono raggruppati in categorie, che possono contenere altre categorie.\nOsserva Cliente e le sue sottoclassi Privato e Azienda, poi confronta l’associazione fra ordine e fattura con quella fra prodotti e categorie. RigaOrdine dipende dall’ordine anche per essere identificata.\nPassando al logico puoi seguire la trasformazione di queste strutture in tabelle e collegamenti. Il codice SQL è configurato per HSQLDB. Il riepilogo segnala le regole che richiedono altri controlli, come la presenza di righe negli ordini.");
 if(key=="purchase")text=QString::fromUtf8("Gli acquisti di automobili\nUna persona può acquistare più automobili, anche dello stesso modello in momenti diversi. Ogni acquisto riguarda una persona e un modello di automobile. DataAcquisto, PrezzoAcquisto e Targa descrivono quel particolare acquisto.\nQueste informazioni appartengono all’entità Acquisto: il prezzo pagato, per esempio, può cambiare da una vendita all’altra anche quando il modello è lo stesso. IdAcquisto permette di distinguere ogni operazione.\nNel logico, la tabella Acquisto contiene i riferimenti alla persona e al modello. PrezzoAcquisto ha tipo Valuta: nel codice SQL diventa DECIMAL(19,4), adatto a conservare importi con quattro cifre decimali.");
 if(key=="suppliers")text=QString::fromUtf8("Fornitori e prodotti\nUn fornitore può fornire più prodotti, mentre ogni prodotto viene fornito da un solo fornitore. Ammettiamo di registrare un fornitore anche prima di aver inserito i suoi prodotti: la sua partecipazione è quindi facoltativa.\nNella vista UML-like, la zampa di gallina accanto a Prodotto indica che i prodotti possono essere molti. Il tratteggio vicino a Fornitore indica che un fornitore può non avere ancora prodotti collegati.\nGenera il logico e cerca nella tabella Prodotto la colonna che rimanda al fornitore. Se vuoi ammettere soltanto fornitori con almeno un prodotto, modifica la cardinalità e leggi nel riepilogo quale ulteriore controllo serve.");
 if(key=="Passeggeri_e_voli")text=QString::fromUtf8("Passeggeri e voli\nUn passeggero viaggia su uno o più voli. Uno stesso volo può essere scelto da più passeggeri, ma può anche non avere ancora prenotazioni. In questo esempio, un volo è una singola partenza, con una propria data, e non una rotta generica.\nIl passeggero partecipa ad almeno un volo (1,N); il volo può avere zero o più passeggeri (0,N). L’associazione è quindi molti a molti.\nGenera il logico e osserva la tabella che raccoglie gli abbinamenti fra passeggeri e voli. Le chiavi esterne controllano che i riferimenti siano validi; per verificare che ogni passeggero abbia almeno un volo occorre un controllo ulteriore.");
 if(key=="Studenti_e_corsi_di_laurea")text=QString::fromUtf8("Studenti e corsi di laurea\nOgni studente deve essere iscritto a un solo corso di laurea. Un corso può accogliere più studenti; in questo esempio può anche essere registrato prima di ricevere iscrizioni.\nLo studente partecipa all’associazione una sola volta e obbligatoriamente (1,1). Il corso di laurea può partecipare zero o più volte (0,N).\nQuando generi il logico, cerca nella tabella Studente il riferimento al corso di laurea: per ogni studente quel valore è obbligatorio. Se vuoi descrivere soltanto corsi che hanno già iscritti, puoi cambiare il minimo del corso da zero a uno e discutere come verificare questa regola.");
 if(key=="Scelta_dei_corsi")text=QString::fromUtf8("La scelta dei corsi universitari\nOgni studente deve scegliere almeno quattro corsi. Uno stesso corso può essere scelto da più studenti, oppure non avere ancora iscritti. Uno studente e un corso possono quindi partecipare a più abbinamenti.\nIl diagramma rappresenta l’associazione molti a molti con (1,N) per Studente e (0,N) per Corso. Il minimo esatto di quattro non è rappresentato da queste cardinalità: la frase nella nota e il nome dell’associazione ricordano la richiesta, ma non la fanno rispettare.\nNel logico viene creata una tabella con le scelte degli studenti. Per controllare il requisito completo bisogna anche contare i corsi scelti da ciascuno studente e verificare che siano almeno quattro.");
 if(key=="Corsi_e_docenti")text=QString::fromUtf8("Corsi e docenti\nOgni corso universitario è tenuto da un solo docente. Un docente può insegnare in più corsi; ammettiamo anche di registrare docenti ai quali non è stato ancora assegnato un corso.\nLa partecipazione di Corso è obbligatoria e singola (1,1). Quella di Docente è facoltativa e può ripetersi (0,N).\nPassando al logico, osserva il riferimento al docente nella tabella Corso. Deve essere compilato per ogni corso. Se consideri soltanto docenti già incaricati, imposta (1,N) per Docente: il riepilogo ti ricorda che la presenza di almeno un corso per ciascun docente richiede un altro controllo.");
 if(key=="Persone_e_genitori")text=QString::fromUtf8("Persone e genitori\nUna persona può essere figlia di altre persone e, a sua volta, avere figli. Per descrivere questi legami colleghiamo Persona a se stessa, distinguendo i ruoli figlio e genitore.\nNel ruolo di figlio ogni persona ha uno o più genitori (1,N); nel ruolo di genitore può avere zero o più figli (0,N). Il diagramma non fissa il numero esatto dei genitori.\nNel logico compare una tabella che registra le coppie figlio-genitore. Per usare il modello con dati reali bisogna decidere come trattare i genitori non presenti nell’archivio. Servono inoltre controlli per impedire che una persona sia genitore di se stessa o che una catena di legami torni alla persona di partenza.");
 if(key=="Persone_e_madri")text=QString::fromUtf8("Persone e madri\nOgni persona ha una madre; una stessa madre può avere più figli. L’associazione collega Persona a se stessa, una volta nel ruolo di figlio e una volta nel ruolo di madre.\nOgni persona ha un solo collegamento verso la propria madre (1,1), mentre può non avere figli oppure averne più di uno (0,N). Il ruolo madre indica quindi come viene usato quel lato dell’associazione, non un’entità separata.\nNel logico, una colonna della tabella Persona rimanda alla stessa tabella. Discuti come registrare una persona quando sua madre non è presente nell’archivio e come impedire riferimenti a se stessa o catene di parentela circolari.");
 if(key=="Pezzi_e_parti")text=QString::fromUtf8("I pezzi e le parti di un prodotto\nUn pezzo è composto da altri pezzi, usati come parti. La stessa entità Pezzo compare quindi nei ruoli composto e componente. Seguendo la frase dell’esercizio, entrambi i ruoli hanno cardinalità (1,N).\nQuesta lettura comporta una conseguenza: ogni pezzo deve avere componenti ed essere componente di un altro pezzo. In un archivio finito si finisce così per tornare a un pezzo già incontrato.\nPer descrivere un prodotto reale occorre ammettere anche pezzi elementari, senza componenti, e prodotti finali, non contenuti in altri pezzi. Prova a usare (0,N) e discuti come evitare i cicli. Per registrare la quantità di ogni componente, puoi introdurre un’entità associativa.");
 if(key=="Ricette_e_ingredienti")text=QString::fromUtf8("Ricette e ingredienti\nUna ricetta utilizza ingredienti e può richiamare altre ricette. Per esempio, la preparazione di un piatto di pasta può richiedere un pesto descritto in una ricetta separata.\nIl diagramma contiene un’associazione molti a molti fra ricette e ingredienti e un’associazione di Ricetta con se stessa, per i richiami ad altre preparazioni. Una ricetta può non richiamarne altre e può non essere richiamata da nessuna.\nNel logico troverai due tabelle di collegamento. Se ammetti ricette formate soltanto da altre ricette, rendi facoltativo l’uso di ingredienti diretti. Per aggiungere quantità e unità di misura puoi introdurre un’entità associativa; controlla anche che i richiami non formino cicli.");
 if(key=="limit")text=QString::fromUtf8("Un’azienda: esempio per il test limite\nQuesto esempio riunisce numerose entità e associazioni per verificare il comportamento dell’applicazione con un diagramma ampio. È adatto a chi ha già esplorato gli esempi più piccoli.\nComincia da un’entità, osserva il suo identificatore e segui le associazioni che la collegano alle altre. Passa poi al modello logico e usa Mostra origine per capire da quali elementi concettuali provengono le colonne.\nSalva una copia prima di modificare il progetto. Dopo aver cambiato il concettuale, leggi il riepilogo di Aggiorna logico: alcune modifiche possono richiedere la sostituzione o la rimozione di tabelle e colonne.");
 if(text.isEmpty())return;
 DiagramNote note;note.id="note-example-"+key;note.text=text;note.size={720,300};
 auto position=[&](bool uml){double left=1e9,right=-1e9,bottom=0;for(const auto &o:model.objects){if(o.kind=="entity"){auto pos=uml?o.uml:o.chen;left=qMin(left,pos.x());right=qMax(right,pos.x());}if(uml&&o.kind=="attribute")continue;double half=uml&&o.kind=="entity"?qMax(78.,48.+model.attributes(o.id).size()*30.)/2+50:80;bottom=qMax(bottom,(uml?o.uml:o.chen).y()+half);}return QPointF(left<=right?(left+right)/2:0,bottom+180);};
 note.chen=position(false);note.uml=position(true);LogicalSchema schema;QString error;
 if(LogicalSchema::parse(model.logical,schema,error)&&!schema.tables.isEmpty()){double left=1e9,right=-1e9,bottom=0;for(const auto &t:schema.tables){left=qMin(left,t.position.x());right=qMax(right,t.position.x());bottom=qMax(bottom,t.position.y()+qMax(80.,48.+t.columns.size()*30.)/2);}note.logical={(left+right)/2,bottom+200};}
 else{int count=0;for(const auto &o:model.objects)count+=o.kind=="entity"||(o.kind=="relation"&&o.cardA.endsWith("N")&&o.cardB.endsWith("N"));note.logical={215,double(((qMax(1,count)-1)/3)*360+500)};}
 if(auto existing=model.note(note.id))*existing=note;else model.notes<<note;
}
inline Model ordersExample(){auto model=Model::example();annotateExample(model,"orders");return model;}
